import{_ as a,a as t,c as s,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · 单元 3 复习与自测 · 第58–66课","description":"L49–L72 原创练习和答案解析。","frontmatter":{"title":"第二册：实践与进步 · 单元 3 复习与自测 · 第58–66课","description":"L49–L72 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-2/unit-03/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 3 复习与自测","summary":"L49–L72 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 3 复习与自测 · 第49–57课","link":"/life/english/new-concept/book-2/unit-03/review-part-01"},"next":{"text":"第二册：实践与进步 · 单元 3 复习与自测 · 第67–72课","link":"/life/english/new-concept/book-2/unit-03/review-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 3 复习与自测 · 第49–57课","link":"/life/english/new-concept/book-2/unit-03/review-part-01"},"next":{"text":"第二册：实践与进步 · 单元 3 复习与自测 · 第67–72课","link":"/life/english/new-concept/book-2/unit-03/review-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/review-part-02.md","filePath":"life/english/new-concept/book-2/unit-03/review-part-02.md"}'),n={name:"life/english/new-concept/book-2/unit-03/review-part-02.md"};function l(r,e,i,h,d,p){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-单元-3-复习与自测-·-第58–66课" tabindex="-1">第二册：实践与进步 · 单元 3 复习与自测 · 第58–66课 <a class="header-anchor" href="#第二册-实践与进步-·-单元-3-复习与自测-·-第58–66课" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 3 复习与自测 · 第58–66课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-03/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-58-·-时间、原因与让步从句" tabindex="-1">Lesson 58 · 时间、原因与让步从句 <a class="header-anchor" href="#lesson-58-·-时间、原因与让步从句" aria-label="Permalink to &quot;Lesson 58 · 时间、原因与让步从句 {#lesson-58-·-时间、原因与让步从句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Although the flood damaged the garden, it led to better drainage.</p><h3 id="练习-1-9" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-9" aria-label="Permalink to &quot;练习 1 {#练习-1-9}&quot;">​</a></h3><p>补全：The damage led ___ a new drainage plan.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> lead to 为固定搭配。</p></details><p><strong>表达迁移：</strong> 写一个损失后得到改善的例子，避免把损失本身说成完全有益。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Although the flood damaged the garden, it led to better drainage. Residents replaced the blocked pipes. The next heavy shower caused no flooding.</p><p>第一句的组织方式：Although 从句承认不利事实，主句 led to 引出后续结果；it 指 flood。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Although ..., but ... 在标准英语中不作这种成对连接；保留一个连接词。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-058">回看本课</a></p><h2 id="lesson-59-·-动词、宾语与补足语" tabindex="-1">Lesson 59 · 动词、宾语与补足语 <a class="header-anchor" href="#lesson-59-·-动词、宾语与补足语" aria-label="Permalink to &quot;Lesson 59 · 动词、宾语与补足语 {#lesson-59-·-动词、宾语与补足语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The new flap lets the cat enter without waking us.</p><h3 id="练习-1-10" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-10" aria-label="Permalink to &quot;练习 1 {#练习-1-10}&quot;">​</a></h3><p>选 enter/to enter：The flap lets the cat ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> enter</p><p><strong>解析：</strong> let 的主动使役结构接不带 to 的原形。</p></details><p><strong>表达迁移：</strong> 写三句帮助宠物适应新物件的过程，包含 let 和 without doing。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The new flap lets the cat enter without waking us. At first, the cat was afraid of it. A week later, it used the flap confidently.</p><p>第一句的组织方式：lets 为单数谓语，the cat 是宾语，enter 是原形补足语；without waking 为介词加动名词。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：lets the cat to enter 多了 to；allows the cat enter 则少了 to。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-059">回看本课</a></p><h2 id="lesson-60-·-将来表达与安排" tabindex="-1">Lesson 60 · 将来表达与安排 <a class="header-anchor" href="#lesson-60-·-将来表达与安排" aria-label="Permalink to &quot;Lesson 60 · 将来表达与安排 {#lesson-60-·-将来表达与安排}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The guide predicted that we would see clear skies by evening.</p><h3 id="练习-1-11" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-11" aria-label="Permalink to &quot;练习 1 {#练习-1-11}&quot;">​</a></h3><p>填 will/would：He predicted that the rain ___ stop.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> would</p><p><strong>解析：</strong> 主句从过去视角转述未来，常用 would。</p></details><p><strong>表达迁移：</strong> 写一次天气预测与实际结果，明确谁预测、如何准备、最后怎样。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The guide predicted that we would see clear skies by evening. We kept our raincoats anyway. The clouds finally broke just before sunset.</p><p>第一句的组织方式：predicted 为过去报告动词，would see 是从过去视角看将来，by evening 给出截止时间。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：predict 不等于 promise；前者是判断未来，后者是作出承担义务的承诺。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-060">回看本课</a></p><h2 id="lesson-61-·-被动语态与信息重点" tabindex="-1">Lesson 61 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-61-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 61 · 被动语态与信息重点 {#lesson-61-·-被动语态与信息重点}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> By Friday, the replacement camera will have been tested twice.</p><h3 id="练习-1-12" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-12" aria-label="Permalink to &quot;练习 1 {#练习-1-12}&quot;">​</a></h3><p>补全被动：The camera will have ___ tested twice.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> been</p><p><strong>解析：</strong> 将来完成时被动结构为 will have been done。</p></details><p><strong>表达迁移：</strong> 写一份设备检查计划，区分测试截止、结果评审与批准条件。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>By Friday, the replacement camera will have been tested twice. Engineers will compare the results on Saturday. They will approve the launch only if both tests pass.</p><p>第一句的组织方式：will have been tested 为将来完成时被动，By Friday 给出截止点，twice 是次数。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：will have tested 若主语是 camera 会变成摄像机执行测试；此处需 been 表被动。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-061">回看本课</a></p><h2 id="lesson-62-·-完成进行时与持续活动" tabindex="-1">Lesson 62 · 完成进行时与持续活动 <a class="header-anchor" href="#lesson-62-·-完成进行时与持续活动" aria-label="Permalink to &quot;Lesson 62 · 完成进行时与持续活动 {#lesson-62-·-完成进行时与持续活动}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The volunteers had been planting seeds for hours when the rain began.</p><h3 id="练习-1-13" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-13" aria-label="Permalink to &quot;练习 1 {#练习-1-13}&quot;">​</a></h3><p>填 plant：They had been ___ seeds for hours.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> planting</p><p><strong>解析：</strong> 过去完成进行时为 had been doing。</p></details><p><strong>表达迁移：</strong> 描述一次持续劳动被天气打断的经历，补充一个较晚的观察结果。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The volunteers had been planting seeds for hours when the rain began. They stopped to protect the tools. A month later, small green shoots appeared.</p><p>第一句的组织方式：had been planting 强调雨开始前持续的活动，when rain began 提供过去参照点。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：had been planted 是被动或状态相关结构，不表示志愿者持续播种；用 planting。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-062">回看本课</a></p><h2 id="lesson-63-·-间接引语与视角转换" tabindex="-1">Lesson 63 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-63-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 63 · 间接引语与视角转换 {#lesson-63-·-间接引语与视角转换}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The host asked me not to repeat the joke.</p><h3 id="练习-1-14" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-14" aria-label="Permalink to &quot;练习 1 {#练习-1-14}&quot;">​</a></h3><p>填否定位置：The host asked me ___ repeat it.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> not to</p><p><strong>解析：</strong> 否定不定式通常为 not to do。</p></details><p><strong>表达迁移：</strong> 写一次说话不合场合后的调整，转述一个否定请求。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The host asked me not to repeat the joke. I had mistaken the occasion for an informal party. I apologised and moved to the main topic.</p><p>第一句的组织方式：asked 后接 me，再用 not to repeat 转述否定请求；the joke 是 repeat 的宾语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：asked me to not repeat 有时可见，但常规教学优先 not to repeat；did not ask 与 asked not 不同。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-063">回看本课</a></p><h2 id="lesson-64-·-非真实条件句" tabindex="-1">Lesson 64 · 非真实条件句 <a class="header-anchor" href="#lesson-64-·-非真实条件句" aria-label="Permalink to &quot;Lesson 64 · 非真实条件句 {#lesson-64-·-非真实条件句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> If the earlier plan had succeeded, the route would have opened sooner.</p><h3 id="练习-1-15" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-15" aria-label="Permalink to &quot;练习 1 {#练习-1-15}&quot;">​</a></h3><p>填 succeed：If the plan had ___, the route would have opened sooner.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> succeeded</p><p><strong>解析：</strong> had 后要求过去分词。</p></details><p><strong>表达迁移：</strong> 写一个未实施方案的三句回顾，包括假设结果、实际障碍和后来变化。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>If the earlier plan had succeeded, the route would have opened sooner. However, funding was not available. A later team developed a different design.</p><p>第一句的组织方式：had succeeded 是过去反事实条件，would have opened 是未发生的假设结果，sooner 比较时间早晚。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：would have open 缺少过去分词；have 后应为 opened。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-064">回看本课</a></p><h2 id="lesson-65-·-动词、宾语与补足语" tabindex="-1">Lesson 65 · 动词、宾语与补足语 <a class="header-anchor" href="#lesson-65-·-动词、宾语与补足语" aria-label="Permalink to &quot;Lesson 65 · 动词、宾语与补足语 {#lesson-65-·-动词、宾语与补足语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The keeper made the elephant move towards a basket of fruit.</p><h3 id="练习-1-16" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-16" aria-label="Permalink to &quot;练习 1 {#练习-1-16}&quot;">​</a></h3><p>选 move/to move：The keeper made the elephant ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> move</p><p><strong>解析：</strong> make 的主动使役结构接原形。</p></details><p><strong>表达迁移：</strong> 描述一次非对抗方式解决阻塞的过程，避免夸大动物心理。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The keeper made the elephant move towards a basket of fruit. The road soon became clear. Nobody needed to shout at the animal.</p><p>第一句的组织方式：made 后接宾语 elephant，再用原形 move 作补足语；towards 只说明方向。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：made the elephant to move 在主动句中多余 to；被动才常用 was made to move。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-065">回看本课</a></p><h2 id="lesson-66-·-完成进行时与持续活动" tabindex="-1">Lesson 66 · 完成进行时与持续活动 <a class="header-anchor" href="#lesson-66-·-完成进行时与持续活动" aria-label="Permalink to &quot;Lesson 66 · 完成进行时与持续活动 {#lesson-66-·-完成进行时与持续活动}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> A jar of honey has been leaking inside the delivery van.</p><h3 id="练习-1-17" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-17" aria-label="Permalink to &quot;练习 1 {#练习-1-17}&quot;">​</a></h3><p>填 has/have：A jar of honey ___ been leaking.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> has</p><p><strong>解析：</strong> 主语核心 jar 是单数。</p></details><p><strong>表达迁移：</strong> 写一次根据气味或痕迹发现问题的过程，区分初步怀疑与最终发现。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A jar of honey has been leaking inside the delivery van. The driver first suspected the engine. He found the sticky trail beside a damaged box.</p><p>第一句的组织方式：A jar 为单数主语，has been leaking 表持续过程；of honey 说明内容物，inside 为地点。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：honey have been 错误；这里主语 a jar of honey 的核心是 jar，配 has。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-066">回看本课</a></p>',76)])])}const m=a(n,[["render",l]]);export{u as __pageData,m as default};
